mapper.select:
select f.feedback_id, f.visitor_uid, f.record_id, f.plant_id, p.plant_name, f.feedback_type,
       f.feedback_reason, f.extra_note, f.create_time
from zx_feedback_record f
left join zx_plant p on f.plant_id = p.plant_id
where 1 = 1
and f.visitor_uid like concat('%', #{visitorUid}, '%')
and f.record_id = #{recordId}
and f.plant_id = #{plantId}
and f.feedback_type = #{feedbackType}
and f.create_time >= #{params.beginTime}
and f.create_time <= #{params.endTime}
order by f.create_time desc, f.feedback_id desc
